script:
var EPOCHS = {{epochs}};
var SPEED = {{speed}};

var stageGroup = document.getElementById('stages');
var dotGroup = document.getElementById('dots');
var caption = document.getElementById('caption');
var accuracy = document.getElementById('accuracy');

// 三个阶段（横向卡片）
var STAGES = [
  { x: 24, title: '数据', hint: '例子 + 答案' },
  { x: 164, title: '训练', hint: '反复对答案、调参数' },
  { x: 318, title: '预测', hint: '给新例子做判断' }
];

var stageNodes = [];
for (var s = 0; s < STAGES.length; s += 1) {
  var stage = STAGES[s];
  var rect = Sandbox.svgEl('rect');
  rect.setAttribute('x', String(stage.x));
  rect.setAttribute('y', '20');
  rect.setAttribute('width', '118');
  rect.setAttribute('height', '70');
  rect.setAttribute('rx', '12');
  rect.setAttribute('fill', '#ffffff');
  rect.setAttribute('stroke', '#d6ddec');
  rect.setAttribute('stroke-width', '1.6');
  stageGroup.appendChild(rect);

  var title = Sandbox.svgEl('text');
  title.setAttribute('x', String(stage.x + 59));
  title.setAttribute('y', '48');
  title.setAttribute('text-anchor', 'middle');
  title.setAttribute('style', 'font-size:15px;font-weight:650;fill:#12233b');
  title.textContent = stage.title;
  stageGroup.appendChild(title);

  var hint = Sandbox.svgEl('text');
  hint.setAttribute('x', String(stage.x + 59));
  hint.setAttribute('y', '70');
  hint.setAttribute('text-anchor', 'middle');
  hint.setAttribute('style', 'font-size:11.5px;fill:#5b6b82');
  hint.textContent = stage.hint;
  stageGroup.appendChild(hint);

  // 阶段之间的箭头
  if (s < STAGES.length - 1) {
    var arrow = Sandbox.svgEl('path');
    var ax = stage.x + 118;
    arrow.setAttribute('d', 'M' + (ax + 4) + ' 55 L' + (ax + 18) + ' 55 M' + (ax + 12) + ' 50 L' + (ax + 18) + ' 55 L' + (ax + 12) + ' 60');
    arrow.setAttribute('stroke', '#d6ddec');
    arrow.setAttribute('stroke-width', '2');
    arrow.setAttribute('fill', 'none');
    stageGroup.appendChild(arrow);
  }
  stageNodes.push({ rect: rect, stage: stage });
}

// 数据点：8 个「例子」，每个带一个答案标签（猫/不是猫）
var SAMPLES = [1, 1, 0, 1, 0, 0, 1, 0];
var LABELS = ['猫', '猫', '不是猫', '猫', '不是猫', '不是猫', '猫', '不是猫'];

var dots = [];
for (var d = 0; d < SAMPLES.length; d += 1) {
  var dot = Sandbox.svgEl('circle');
  dot.setAttribute('cx', String(40 + d * 52));
  dot.setAttribute('cy', '140');
  dot.setAttribute('r', '16');
  dot.setAttribute('fill', SAMPLES[d] === 1 ? '#2f6fd0' : '#eef2f8');
  dot.setAttribute('stroke', SAMPLES[d] === 1 ? '#2f6fd0' : '#9aa7bb');
  dot.setAttribute('stroke-width', '1.5');
  dotGroup.appendChild(dot);

  var label = Sandbox.svgEl('text');
  label.setAttribute('x', String(40 + d * 52));
  label.setAttribute('y', '170');
  label.setAttribute('text-anchor', 'middle');
  label.setAttribute('class', 'axis-label');
  label.textContent = LABELS[d];
  dotGroup.appendChild(label);
  dots.push(dot);
}

/* 训练进度 → 正确率（教学用曲线：一开始很差，练几轮之后稳定下来）。 */
function accuracyAt(epoch) {
  if (epoch <= 0) return 0.5;
  return Math.min(0.94, 0.5 + 0.16 * epoch - 0.01 * epoch * epoch);
}

Sandbox.play(function () {
  var steps = [];
  var shown = 0;

  steps.push({
    targets: stageNodes[0].rect,
    stroke: '#2f6fd0',
    strokeWidth: 3,
    duration: 320 * SPEED,
    begin: function () {
      caption.textContent = '第一步 · 数据：想让它认猫，就得给它很多猫的照片，而且每一张都要标好「这是猫 / 这不是猫」。';
      accuracy.textContent = '正确率 —';
    }
  });

  for (var i = 0; i < dots.length; i += 1) {
    steps.push({
      targets: dots[i],
      opacity: [0, 1],
      scale: [0.4, 1],
      duration: 140 * SPEED,
      begin: (function (index) {
        return function () {
          shown += 1;
          caption.textContent = '收了第 ' + shown + ' 个例子：' + LABELS[index] + '，课本要配答案，机器才知道什么是对的。';
        };
      })(i)
    });
  }

  steps.push({
    targets: stageNodes[0].rect,
    stroke: '#d6ddec',
    strokeWidth: 1.6,
    duration: 200,
    complete: function () {
      anime({ targets: stageNodes[1].rect, stroke: '#d97706', strokeWidth: [1.6, 3], duration: 300, direction: 'alternate' });
    }
  });

  for (var epoch = 1; epoch <= EPOCHS; epoch += 1) {
    steps.push({
      targets: stageNodes[1].rect,
      duration: 420 * SPEED,
      begin: (function (round) {
        return function () {
          caption.textContent =
            '第二步 · 训练第 ' + round + ' 轮：拿一个例子让它猜，猜错了就把参数往「更接近答案」的方向调一点。';
          accuracy.textContent = '正确率 ' + Math.round(accuracyAt(round - 1) * 100) + '%';
        };
      })(epoch),
      complete: (function (round) {
        return function () {
          accuracy.textContent = '正确率 ' + Math.round(accuracyAt(round) * 100) + '%';
          anime({
            targets: dots,
            translateY: [-2, 0],
            duration: 200,
            delay: anime.stagger(30),
            easing: 'easeOutQuad'
          });
        };
      })(epoch)
    });
  }

  steps.push({
    targets: stageNodes[1].rect,
    stroke: '#d6ddec',
    strokeWidth: 1.6,
    duration: 200,
    complete: function () {
      anime({ targets: stageNodes[2].rect, stroke: '#1f9d63', strokeWidth: [1.6, 3], duration: 300, direction: 'alternate' });
    }
  });

  steps.push({
    targets: dots.slice(0, 3),
    opacity: [1, 0.35],
    duration: 320 * SPEED,
    begin: function () {
      caption.textContent = '第三步 · 预测：拿一个从没见过的新例子来考它，这才是真正要看的表现。';
    },
    complete: function () {
      accuracy.textContent = '正确率 ' + Math.round(accuracyAt(EPOCHS) * 100) + '%（新例子）';
      Sandbox.progress(1);
    }
  });

  var timeline = anime.timeline({ autoplay: true, easing: 'easeInOutQuad' });
  for (var t = 0; t < steps.length; t += 1) timeline.add(steps[t]);
  timeline.play();

  var duration = timeline.duration || 5200;
  return {
    pause: function () { timeline.pause(); },
    play: function () { timeline.play(); },
    restart: function () { timeline.restart(); },
    finished: {
      then: function (resolve) {
        var elapsed = 0;
        var timer = setInterval(function () {
          elapsed += 100;
          if (timeline.completed || elapsed > duration + 800) {
            clearInterval(timer);
            resolve();
          }
          Sandbox.progress(Math.min(1, elapsed / duration));
        }, 100);
      }
    }
  };
});

Sandbox.ready({ template: 'train-predict', epochs: EPOCHS });
